const SYSTEMS = ['PRIV', 'KEL', 'MEZZO', 'BRIGIT', 'SOBEK', 'ANUBIS', 'OMEGA', 'SIA', 'MPETI', 'HAPI'];

function chooseSystems(index: number) {
  const first = SYSTEMS[index % SYSTEMS.length];
  const second = SYSTEMS[(index + 3) % SYSTEMS.length];
  return [first, second];
}

